//! The action catalogue: the built-in actions and the actions of every plugin in
//! the plugins folder (their actions.json). Made by a script; do not edit by hand.
#![allow(dead_code)]

pub struct Field {
    pub key: &'static str,
    pub label: &'static str,
    /// keys, text, number, url, select, pages, dynamic (a list the plugin fills while it runs)
    pub kind: &'static str,
    pub options: &'static [&'static str],
    pub def: &'static str,
    pub placeholder: &'static str,
    pub help: &'static str,
    pub unit: &'static str,
    pub required: bool,
}

pub struct Action {
    pub id: &'static str,
    pub label: &'static str,
    pub group: &'static str,
    /// The plugin's folder id, "" for a built-in action.
    pub plugin: &'static str,
    pub plugin_name: &'static str,
    /// An 8x8 glyph name or "png:<plugin>/<file>".
    pub icon: &'static str,
    pub help: &'static str,
    pub states: &'static [&'static str],
    pub knob: bool,
    pub screen: bool,
    pub fields: &'static [Field],
}

pub struct Plugin {
    pub id: &'static str,
    pub name: &'static str,
    pub icon: &'static str,
    pub count: usize,
}

